const PM={qty:['تعداد فروش','عدد'],amt:['مبلغ فروش',''],gross:['سود ناخالص مواد','']};
function trendData(p){const wk=RC.span(st.end,Math.max(3,st.n)),sm=salesData(wk),menu=menuMap(),sum=RC.salesSummary(sm,menu,wk);
 const ents=[['all','همهٔ منو'],...sum.groups.slice().sort((a,b)=>GI(a.id)-GI(b.id)).map(g=>['g:'+g.id,'گروه '+g.label])],cats=sum.groups.flatMap(g=>g.cats.map(c=>['c:'+c.name,c.name])),items=sum.rows.slice(0,80).map(r=>['i:'+r.id,r.name]);
 if(![...ents,...cats,...items].some(x=>x[0]===st.ent))st.ent='all';
 const sr=RC.entitySeries(sm,menu,st.ent,wk),daily=st.pb==='daily',div=i=>daily?(sm.days[wk[i]]||0):1,has=i=>(sm.days[wk[i]]||0)>0,raw=st.pm==='qty'?sr.qty:st.pm==='amt'?sr.amt:sr.gross;
 const vals=raw.map((v,i)=>has(i)&&div(i)?v/div(i):null),qv=sr.qty.map((v,i)=>has(i)&&div(i)?v/div(i):null),price=sr.qty.map((q,i)=>q?sr.amt[i]/q:null),gr=vals.map((v,i)=>i&&v!==null&&vals[i-1]!==null?RC.growth(v,vals[i-1]):null);
 return{wk,sm,menu,sum,ents,cats,items,sr,daily,vals,qv,price,gr,months:wk.filter((k,i)=>has(i)).length}}
function ranking(d){const i=d.wk.length-1,a=d.wk[i-1],b=d.wk[i],da=d.daily?d.sm.days[a]:1,db=d.daily?d.sm.days[b]:1;if(!d.sm.days[a]||!d.sm.days[b])return null;
 const rows=[];for(const [id,o] of d.sm.items){const qa=(o.qty[a]||0)/da,qb=(o.qty[b]||0)/db;if((o.qty[a]||0)<5&&(o.qty[b]||0)<5)continue;const g=RC.growth(qb,qa);if(g===null)continue;rows.push({name:S(d.menu.get(id)?.name)||o.name||id,g,qa,qb})}
 rows.sort((x,y)=>y.g-x.g);return{a,b,up:rows.filter(r=>r.g>0).slice(0,6),down:rows.filter(r=>r.g<0).slice(-6).reverse()}}
