 const ctl=`<label class="rp-end"><span class="muted">محصول یا گروه</span><select class="select" data-rpset="ent" style="max-width:220px">${opt(d.ents)}<optgroup label="دسته‌ها">${opt(d.cats)}</optgroup><optgroup label="آیتم‌های پرفروش">${opt(d.items)}</optgroup></select></label>${segBtn('pm',[['qty','تعداد'],['amt','مبلغ'],['gross','سود ناخالص']])}${segBtn('pb',[['total','جمع ماه'],['daily','میانگین روز']])}`;
 const head=srcLine()+bar(p,'روند محصولات —',ctl);if(!d.sum.qty&&!d.sum.amt)return head+noSales(p);
 const name=[...d.ents,...d.cats,...d.items].find(x=>x[0]===st.ent)?.[1]||'',g1=d.gr[last],gq=last&&d.qv[last]!==null&&d.qv[last-1]!==null?RC.growth(d.qv[last],d.qv[last-1]):null,gp=last&&d.price[last]&&d.price[last-1]?RC.growth(d.price[last],d.price[last-1]):null,rk=ranking(d);
 const mg=i=>d.sr.amt[i]?d.sr.gross[i]/d.sr.amt[i]*100:null,ga=last&&d.sm.days[d.wk[last]]&&d.sm.days[d.wk[last-1]]?RC.growth(d.sr.amt[last]/(d.daily?d.sm.days[d.wk[last]]:1),d.sr.amt[last-1]/(d.daily?d.sm.days[d.wk[last-1]]:1)):null;
