 <div class="grid grid-2 mt">${P.card({title:`${esc(name)} — ${PM[st.pm][0]}`,sub:`${unit}${d.daily?' در هر روزِ دارای فروش':' در ماه'}`,body:'<div class="chart" id="rpTr" style="height:270px"></div>'})}${P.card({title:'رشد یا افت نسبت به ماه قبل',sub:'درصد · ماه اول مبنای قبلی ندارد',body:d.gr.some(v=>v!==null)?'<div class="chart" id="rpGr" style="height:270px"></div>':P.note('برای رشد ماه به ماه دست‌کم دو ماهِ پشت سر هم فایل فروش لازم است.','info')})}</div>
