const SG=['آشپزخانه','سالن','خدمات','مدیریت'],SGI=n=>{const i=SG.indexOf(n);return i<0?4:i},PSTATE={before:['قبل از شروع حقوق','neutral'],future:['آینده','neutral'],current:['در جریان','info'],open:['قطعی نشده','warning'],closed:['قطعی‌شده','success']};
